function spec(name) {
  const icon = ICONS[name] || [];
  return Array.isArray(icon) ? { vb: [0, 0, 64, 64], rule: 'evenodd', flip: false, parts: icon } : icon;
}

const svgPart = (p, rule) => (typeof p === 'string'
  ? `<path d="${p}" fill="currentColor" fill-rule="${rule}"/>`
  : `<path d="${p.d}" fill="none" stroke="currentColor" stroke-width="${p.s}" stroke-linecap="round" stroke-linejoin="round"/>`);

function iconSVG(name, cls = 'glyph') {
  const { vb, rule, flip, parts } = spec(name);
  const [x, , w] = vb;
  const body = parts.map((p) => svgPart(p, rule)).join('');
  const inner = flip ? `<g transform="matrix(-1 0 0 1 ${2 * x + w} 0)">${body}</g>` : body;
  return `<svg class="${cls}" viewBox="${vb.join(' ')}" aria-hidden="true">${inner}</svg>`;
}

const compiled = new Map();
function compile(name) {
  if (!compiled.has(name)) {
    const { parts } = spec(name);
    compiled.set(name, parts.map((p) => (typeof p === 'string'
      ? { fill: new Path2D(p) }
      : { stroke: new Path2D(p.d), w: p.s })));
  }
  return compiled.get(name);
}

// Draw a glyph centered at (x, y), fitting a `size` px square. `mirror` flips it horizontally.
function drawIcon(ctx, name, x, y, size, color, mirror = false) {
  const { vb: [vx, vy, vw, vh], rule, flip } = spec(name);
  const k = size / Math.max(vw, vh);
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(!!flip !== mirror ? -k : k, k);
  ctx.translate(-(vx + vw / 2), -(vy + vh / 2));
  ctx.fillStyle = color;
  ctx.strokeStyle = color;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  for (const part of compile(name)) {
    if (part.fill) ctx.fill(part.fill, rule);
    else { ctx.lineWidth = part.w; ctx.stroke(part.stroke); }
  }
  ctx.restore();
}

return { ICONS, iconSVG, drawIcon };
